import { createRoot } from 'react-dom/client'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { RouterProvider, createRootRoute, createRouter } from '@tanstack/react-router'
import { AgentApprovals } from '__SRC__/components/agent/AgentApprovals.tsx'
import { ApprovalAccess } from '__SRC__/components/agent/ApprovalAccess.tsx'
import { useOwnedAgent } from '__SRC__/managed.ts'
import { focusedApproval } from '__SRC__/owner-route.ts'
import { setSession } from '__SRC__/api.ts'
import { FakeAuthProvider } from './Wallet.tsx'
import '__SRC__/styles.css'
setSession('test-session')
const client = new QueryClient({ defaultOptions: { queries: { retry: false } } })
window.__approvalHarness = { client, sign: null }
function App() {
  const agent = useOwnedAgent('10399')
  return <main style={{maxWidth:800,margin:'auto',padding:24}}>{agent === undefined ? <ApprovalAccess /> : <AgentApprovals managed={agent} posted={[]} focus={focusedApproval(location.search)} />}</main>
}
const router = createRouter({ routeTree: createRootRoute({ component: App }) })
createRoot(document.getElementById('root')!).render(<QueryClientProvider client={client}><FakeAuthProvider><RouterProvider router={router}/></FakeAuthProvider></QueryClientProvider>)

