import { createContext, useContext, useState } from 'react'
const C = createContext(null)
export function FakeAuthProvider({children}) {
  const [signedIn, setSignedIn] = useState(!location.search.includes('signedOut'))
  return <C value={{address:'0x1111111111111111111111111111111111111111',signedIn,signIn:async()=>setSignedIn(true)}}>{children}</C>
}
export const useAuth = () => useContext(C)

